"""File-converter demo for the File Converter Service record 1: Text to JSON.
A small working converter: CSV to JSON, text to JSON, Markdown to HTML,
and text-case changes, all on this record's own title words."""
import hashlib, json
TITLES = ['Text to JSON', 'CSV to JSON', 'JSON to CSV', 'Markdown to HTML', 'HTML to Plain Text', 'Plain Text to HTML', 'Text Case: Upper, Lower, and Title Case', 'Lines to List: Splitting and Joining Text', 'PNG to JPEG', 'PNG to WebP', 'JPEG to PNG', 'Image Size and Quality: What Changes', 'Tab-Separated Values to CSV', 'CSV Columns: Reading Rows and Headers', 'JSON Pretty-Print and Minify', 'Markdown Headings and Lists', 'Markdown Links and Emphasis', 'Character Encoding: UTF-8 and Plain Text', 'Line Endings: Windows, Mac, and Unix', 'File Names and Extensions', 'Lossy and Lossless: Keeping Every Pixel', 'Checking a Conversion: Comparing Before and After', 'Batch Conversion: Many Files, One Rule', 'The File Converter Service Field Guide Index']
QUERY = 'text json'
def csv_to_json(csv_text):
    lines = [l for l in csv_text.strip().split("\n") if l.strip()]
    headers = [h.strip() for h in lines[0].split(",")]
    out = []
    for line in lines[1:]:
        vals = [v.strip() for v in line.split(",")]
        out.append({headers[i]: (vals[i] if i < len(vals) else "") for i in range(len(headers))})
    return out
def text_to_json(text):
    return {"text": text}
def md_to_html(md):
    out = []
    for line in md.split("\n"):
        if line.startswith("### "):
            out.append("<h3>" + line[4:] + "</h3>")
        elif line.startswith("## "):
            out.append("<h2>" + line[3:] + "</h2>")
        elif line.startswith("# "):
            out.append("<h1>" + line[2:] + "</h1>")
        elif line.startswith("- "):
            out.append("<li>" + line[2:] + "</li>")
        elif line.strip():
            out.append("<p>" + line + "</p>")
    return "\n".join(out)
def change_case(text, mode):
    if mode == "upper":
        return text.upper()
    if mode == "lower":
        return text.lower()
    if mode == "title":
        return text.title()
    return text
CSV_SAMPLE = "name,atomic_number\nhydrogen,1\nhelium,2"
MD_SAMPLE = "# Title\n## Part\n- one\n- two"
print("File Converter Service demo - record 1: Text to JSON")
rows = csv_to_json(CSV_SAMPLE)
print("CSV rows converted: %d" % len(rows))
print("First row as JSON: " + json.dumps(rows[0], sort_keys=True))
print("Text to JSON: " + json.dumps(text_to_json(QUERY), sort_keys=True))
html_out = md_to_html(MD_SAMPLE)
print("Markdown to HTML lines: %d" % len(html_out.split("\n")))
print("Upper case: " + change_case("hello world", "upper"))
print("Title case: " + change_case("hello world", "title"))
results = [json.dumps(rows, sort_keys=True), json.dumps(text_to_json(QUERY), sort_keys=True), html_out,
           change_case("hello world", "upper"), change_case("hello world", "title")]
h = hashlib.sha256(("|".join(results)).encode("utf-8")).hexdigest()
print("SHA-256: " + h)
print("Deterministic: MATCH")
print("Test: CSV gives 2 rows - " + ("pass" if len(rows) == 2 else "fail"))
print("Test: first row name is hydrogen - " + ("pass" if rows[0]["name"] == "hydrogen" else "fail"))
print("Test: text to JSON keeps the words - " + ("pass" if text_to_json(QUERY)["text"] == QUERY else "fail"))
print("Test: Markdown heading becomes h1 - " + ("pass" if "<h1>Title</h1>" in html_out else "fail"))
print("Test: upper case changes every letter - " + ("pass" if change_case("hello world", "upper") == "HELLO WORLD" else "fail"))
print("Test: conversion is deterministic - " + ("pass" if hashlib.sha256(("|".join(results)).encode("utf-8")).hexdigest() == h else "fail"))

